class Node:
    """Node of a binary search tree."""
    def __init__(self, key):
        self.key = key          # value stored in the node
        self.left = None        # left child
        self.right = None       # right child


class BinarySearchTree:
    """Simple BST with insert, find and in-order traversal."""
    def __init__(self):
        self.root = None        # root of the tree

    def insert(self, key):
        """Insert a key into the BST. Duplicates are ignored."""
        new_node = Node(key)
        if self.root is None:
            # Tree is empty, new node becomes root
            self.root = new_node
            return

        current = self.root
        while True:
            if key < current.key:
                # Go to left subtree
                if current.left is None:
                    current.left = new_node
                    return
                current = current.left
            elif key > current.key:
                # Go to right subtree
                if current.right is None:
                    current.right = new_node
                    return
                current = current.right
            else:
                # Duplicate key, do nothing
                return

    def find(self, key):
        """Return True if key exists in the BST, False otherwise."""
        current = self.root
        while current is not None:
            if key == current.key:
                return True
            elif key < current.key:
                current = current.left
            else:
                current = current.right
        return False

    def _inorder(self, node, result):
        """Helper recursive in-order traversal."""
        if node is None:
            return
        # Visit left subtree
        self._inorder(node.left, result)
        # Visit node
        result.append(node.key)
        # Visit right subtree
        self._inorder(node.right, result)

    def inorder_traversal(self):
        """Return a list of keys in in-order sorted order."""
        result = []
        self._inorder(self.root, result)
        return result
